Trigger.script:
generic.debounceFunction('eat food', 5, function()
  send('eat food')
end)

local rnum = matches[3]
send('look')

tempTimer(2, function ()

  tfe.gotoRoom(rnum, function ()
    	tempTimer(1, function ()
    		send('gstat ' .. player.name .. ' is now at ' .. tostring(tfe.roomInfo.num))
    	end)
  end)

end)

echo('^^ --- looking at affects...\n')
player.affects = {}


local affectWatcher = tempRegexTrigger([[^([A-Z][a-z]* .+?)\s*(temporary|leech: .*)$]], function ()

  if (matches[3] ~= 'Source') then
	 player.affects[matches[2]] = matches[3]
  end

end)

common.onNextEvent(common.events.PARSED_PROMPT, function()

	killTrigger(affectWatcher)
	raiseEvent(common.events.PARSED_AFFECTS, player.affects)

end)

player.prepped = {}

local prepTrig = tempRegexTrigger([[^\s*(\d+)\s*(.+?)\s*\d+\s*$]], function ()
	player.prepped[matches[3]] = tonumber(matches[2])
end)

common.onNextEvent(common.events.PARSED_PROMPT, function (evt, args)
  cecho('\n<green>PREP:<white> finished parsing prepped spells\n\n')
	killTrigger(prepTrig)
	raiseEvent(common.events.PARSED_PREPARED, player.prepped)
end)

player = player or {}
player.gear = player.gear or {}
player.itemSlot = player.itemSlot or {}

if (matches[2] == 'Equipment') then
	-- start of parsing

  player.gear = {}
  player.itemSlot = {}

  player.gear.parsing = true
	-- cecho(' <--- parsing start')

  -- end on next prompt
  tempPromptTrigger(function()
    	-- end of parsing
    	player.gear.parsing = nil
    	player.gearCurrentSlot = nil

    	raiseEvent(common.events.PARSED_EQUIPMENT)
    	-- cecho(' < --- parsing end')  
  end, 1)

elseif player.gear.parsing then

 	-- if this line has a slot, get rid of the redundant part and set it to be the current slot
	if (matches[2] ~= '') then
		player.gearCurrentSlot = rex.gsub(matches[2], [[^(floating|worn on|worn around|worn about) ]], "", 1)
	end

	local item = common.itemSanitize(matches[4], true)

	player.gear[player.gearCurrentSlot] = player.gear[player.gearCurrentSlot] or {}
	player.gear[player.gearCurrentSlot][matches[3]] = {item = item, condition = matches[5] }

	player.itemSlot[item] = {slot=player.gearCurrentSlot, layer=matches[3]}
	-- cecho(' <--- its some gear ')

end

player.gear = {}
player.itemSlot = {}

player.gear.parsing = nil
player.gearCurrentSlot = nil

raiseEvent(common.events.PARSED_EQUIPMENT)

-- undo the heal added to the queue
healer.reduceQueued();
-- player.prepped[healer.spell] = player.prepped[healer.spell] + 1

murder = murder or {}
murder.silenced = murder.silenced or {}

local vic = matches[2]

if not table.contains(murder.silenced, vic) then
  table.insert(murder.silenced, vic)
end

murder = murder or {} murder.silenced = murder.silenced or {}
local vic = matches[2]
if table.contains(murder.silenced, vic) then table.remove(murder.silenced, table.index_of(murder.silenced, vic)) if #murder.silenced == 0 then murder.silenced = nil end end

improves = improves or {}
improves.pracCooldown = improves.pracCooldown or 40
improves.pracLocked(improves.pracCooldown, 'a real life prac or improve happened')

tempTimer(3, function()
  send('cast undergrowth')
end)

tfe = tfe or {}
tfe.supressNextRoomChange = true
send('queue cast landwalk & cast landbinding')

player.gettingFull = player.gettingFull or false
if (not player.gettingFull) then player.gettingFull = true send('ef & dw & dismount')
tempTimer(2, function () send('sit couch & sit chair & sit pad & sit boulder') expandAlias('sl') common.onFull( function () expandAlias('st') send('mount') -- expandAlias('give all.coin batso & drop all.food & get 2*food')
tempTimer(3, function () player.gettingFull = false expandAlias('gstat ready (' .. player.name .. ')') end)
end) end)
else cecho('\n<green>PREP: <white>already getting full\n') end

tempTimer(1.5, function()
if (gmcp.Char.Vitals.hp > 300) then send('untrap chest') end
end)

-- You open a steel-banded blackened chest.
-- You open a tiny, bloody leather pouch labeled bleh you are carrying.
-- display(matches)

thief = thief or {}

thief.chest = thief.chest or {}

thief.chest.opened = matches[2]

