    send('pick chest')  
  end,

  ['77029'] = function()
    send('search & |search & |search & |search & |pick south & |pick south & |pick south & |pick south & |open south & |gstat south might be open')  
  end,    

  ['77053'] = function()
    send('pick chest')  
  end, 

  ['77029'] = function()
    send('search & |search & |search & |search & |pick south & |pick south & |pick south & |pick south & |open south & |gstat south might be open')  
  end,    

