    improves.resetFiller()
  end, function()
    player.improveNonCombat(function() end, function()
      disableTimer('improve buffs/non combat, with tobac')
      cecho('\n\n<green>IMPS<white>: nothing left to improve\n\n')
    end)      
    improves.resetFiller()
  end)
end)

