player.rescue = function ()
if (not player.rescueEnabled or not player.skills or player.skills.rescue == nil or player.skills.rescue == 0) then return end
local fighting = gmcp.Char.Fighting or {}
-- display(fighting)
for mob, mob in pairs(fighting) do
if (mob.attacking ~= "" and mob.attacking ~= gmcp.Char.Score.name) then local vic = mob.attacking if player.noSaveList[vic] then return end if (group.members[vic] and (vic ~= group.leader or player.saveList[vic]))then cecho('<red> <-- save ' .. vic .. ' (gmcp) ') send('rescue ' .. vic .. ' & rescue ' .. vic) end end
end
end

